from io import BytesIO
import base64
import os
import tempfile


import fitz  # PyMuPDF


from reportlab.platypus import (
    SimpleDocTemplate,
    Paragraph,
    Spacer,
    Image,
    Table,
    TableStyle
)


from reportlab.lib.styles import (
    getSampleStyleSheet,
    ParagraphStyle
)


from reportlab.lib.pagesizes import A4


from reportlab.lib import colors






# ==========================================
# QUESTION CONTENT BUILDER
# ==========================================

def build_question_content(data, styles):

    content = []


    for q in data.get("questions", []):


        question_style = ParagraphStyle(

            "question",

            parent=styles["Normal"],

            fontSize=11,

            leading=16

        )



        content.append(

            Paragraph(

                f"<b>Q{q.get('question_number')}.</b> "
                f"{q.get('question','')}",

                question_style

            )

        )


        content.append(

            Spacer(
                1,
                8
            )

        )



        content.append(

            Paragraph(

                f"<b>Type:</b> {q.get('type','')} "
                f"&nbsp;&nbsp;&nbsp;"
                f"<b>Marks:</b> {q.get('marks','')}",

                styles["Normal"]

            )

        )




        if q.get("options"):


            content.append(

                Spacer(
                    1,
                    5
                )

            )


            content.append(

                Paragraph(

                    "<b>Options:</b>",

                    styles["Normal"]

                )

            )



            for option in q.get("options", []):


                content.append(

                    Paragraph(

                        f"• {option}",

                        styles["Normal"]

                    )

                )



        content.append(

            Spacer(
                1,
                20
            )

        )



    return content







# ==========================================
# DEFAULT EDUAI HEADER
# ==========================================

def add_default_eduai_header(content, styles):


    title_style = ParagraphStyle(

        "eduai_title",

        parent=styles["Title"],

        alignment=1,

        fontSize=24,

        textColor=colors.HexColor("#1E3A8A")

    )


    subtitle_style = ParagraphStyle(

        "eduai_subtitle",

        parent=styles["Normal"],

        alignment=1,

        fontSize=12

    )



    content.append(

        Paragraph(

            "🎓 EduAI",

            title_style

        )

    )



    content.append(

        Paragraph(

            "EduAI Assessment Platform",

            subtitle_style

        )

    )



    content.append(

        Paragraph(

            "AI Powered Academic Assessment System",

            subtitle_style

        )

    )



    content.append(

        Spacer(
            1,
            15
        )

    )



    line = Table(

        [[""]],

        colWidths=[450],

        rowHeights=[3]

    )


    line.setStyle(

        TableStyle(

            [

                (

                    "BACKGROUND",

                    (0,0),

                    (-1,-1),

                    colors.HexColor("#2563EB")

                )

            ]

        )

    )


    content.append(line)



    content.append(

        Spacer(
            1,
            25
        )

    )







# ==========================================
# INFORMATION TABLE
# ==========================================

def add_information_section(content):


    info = [

        [

            "Course Name",

            "____________________"

        ],

        [

            "Instructor",

            "____________________"

        ],

        [

            "Assessment",

            "____________________"

        ],

        [

            "Date",

            "____________________"

        ],

        [

            "Total Marks",

            "____________________"

        ]

    ]



    table = Table(

        info,

        colWidths=[130,250]

    )



    table.setStyle(

        TableStyle(

            [

                (

                    "GRID",

                    (0,0),

                    (-1,-1),

                    0.5,

                    colors.HexColor("#CBD5E1")

                ),

                (

                    "BACKGROUND",

                    (0,0),

                    (0,-1),

                    colors.HexColor("#F1F5F9")

                ),

                (

                    "VALIGN",

                    (0,0),

                    (-1,-1),

                    "MIDDLE"

                )

            ]

        )

    )



    content.append(table)



    content.append(

        Spacer(
            1,
            25
        )

    )





# ==========================================
# CUSTOM LETTERHEAD
# ==========================================

def add_generated_letterhead(

    content,

    styles,

    instruction=None

):


    # Instruction is intentionally ignored
    # to prevent appearing in PDF


    content.append(

        Paragraph(

            "LAIBA",

            styles["Title"]

        )

    )


    content.append(

        Paragraph(

            "ABC University",

            styles["Heading1"]

        )

    )


    content.append(

        Paragraph(

            "Department of Computer Science",

            styles["Heading2"]

        )

    )


    content.append(

        Spacer(
            1,
            20
        )

    )


    add_information_section(

        content

    )


# ==========================================
# EXACT EMBEDDED DEFAULT EDU AI LETTERHEAD
# ==========================================
# This is the exact uploaded EDU AI letterhead PDF.
# It is embedded in this Python file, so no assets folder is required.
_DEFAULT_EDUAI_LETTERHEAD_B64 = """

"""


def _build_default_eduai_letterhead_pdf(data, styles):
    """Use the exact supplied letterhead as the background for the question paper."""
    overlay_buffer = BytesIO()

    overlay_doc = SimpleDocTemplate(
        overlay_buffer,
        pagesize=A4,
        topMargin=195,
        bottomMargin=55,
        leftMargin=50,
        rightMargin=50,
    )

    content = [
        Paragraph(
            "<b>Instructions:</b><br/>"
            "• Answer all questions.<br/>"
            "• Attempt each question carefully.<br/>"
            "• Manage your time effectively.",
            styles["Normal"],
        ),
        Spacer(1, 15),
    ]
    content.extend(build_question_content(data, styles))
    overlay_doc.build(content)
    overlay_buffer.seek(0)

    letterhead_bytes = base64.b64decode(_DEFAULT_EDUAI_LETTERHEAD_B64)
    letterhead_doc = fitz.open(stream=letterhead_bytes, filetype="pdf")
    overlay_doc_fitz = fitz.open(stream=overlay_buffer.getvalue(), filetype="pdf")
    output = fitz.open()

    base_page = letterhead_doc[0]
    rect = base_page.rect

    for page_index in range(max(1, len(overlay_doc_fitz))):
        new_page = output.new_page(width=rect.width, height=rect.height)
        new_page.show_pdf_page(rect, letterhead_doc, 0)
        if len(overlay_doc_fitz):
            new_page.show_pdf_page(rect, overlay_doc_fitz, page_index)

    result = BytesIO()
    output.save(result, garbage=4, deflate=True)
    output.close()
    overlay_doc_fitz.close()
    letterhead_doc.close()
    result.seek(0)
    return result


# ==========================================
# MAIN PDF GENERATOR
# ==========================================

def generate_question_paper_pdf(

    data,

    letterhead_option="Default EduAI Format",

    letterhead_file=None,

    letterhead_instruction=None

):


    buffer = BytesIO()


    styles = getSampleStyleSheet()





    # ======================================
    # DEFAULT EDUAI FORMAT
    # ======================================

    if letterhead_option == "Default EduAI Format":

        default_pdf = _build_default_eduai_letterhead_pdf(
            data,
            styles,
        )

        buffer.write(default_pdf.getvalue())

    # ======================================
    # CUSTOM INSTRUCTIONS FORMAT
    # ======================================

    elif letterhead_option == "Custom Instructions":



        doc = SimpleDocTemplate(

            buffer,

            pagesize=A4,

            topMargin=70,

            bottomMargin=60

        )


        content = []



        add_generated_letterhead(

            content,

            styles,

            letterhead_instruction

        )



        content.extend(

            build_question_content(

                data,

                styles

            )

        )



        doc.build(

            content

        )









    # ======================================
    # UPLOAD LETTERHEAD FORMAT
    # ======================================

    elif letterhead_option == "Upload Letterhead":



        if not letterhead_file:


            raise ValueError(

                "Letterhead file required"

            )



        filename = letterhead_file.name.lower()






        # -------------------------------
        # PDF LETTERHEAD
        # -------------------------------

        if filename.endswith(".pdf"):



            original = fitz.open(

                stream=letterhead_file.read(),

                filetype="pdf"

            )



            page = original[0]


            rect = page.rect



            overlay = fitz.open()



            new_page = overlay.new_page(

                width=rect.width,

                height=rect.height

            )



            y_position = 170



            for q in data.get(

                "questions",

                []

            ):



                text = (

                    f"Q{q.get('question_number')}. "

                    f"{q.get('question')}\n"

                    f"Type: {q.get('type')}   "

                    f"Marks: {q.get('marks')}\n"

                )



                new_page.insert_textbox(

                    fitz.Rect(

                        50,

                        y_position,

                        rect.width - 50,

                        rect.height - 50

                    ),

                    text,

                    fontsize=11

                )



                y_position += 100



                if y_position > rect.height - 100:

                    break





            page.show_pdf_page(

                rect,

                overlay,

                0

            )



            output = BytesIO()



            original.save(

                output

            )



            output.seek(0)



            return output







        # -------------------------------
        # IMAGE LETTERHEAD
        # -------------------------------

        else:



            temp = tempfile.NamedTemporaryFile(

                delete=False,

                suffix=os.path.splitext(filename)[1]

            )



            temp.write(

                letterhead_file.read()

            )


            temp.close()



            doc = SimpleDocTemplate(

                buffer,

                pagesize=A4,

                topMargin=170,

                bottomMargin=60

            )



            content = []



            content.append(

                Image(

                    temp.name,

                    width=400,

                    height=100

                )

            )



            content.append(

                Spacer(

                    1,

                    30

                )

            )



            content.extend(

                build_question_content(

                    data,

                    styles

                )

            )



            doc.build(

                content

            )



            os.remove(

                temp.name

            )






    buffer.seek(0)


    return buffer